  'baekgu.pirateStronger':       { ko: '해적이 더 강해졌다. 파츠 업그레이드해.',
                                   en: 'Pirates are even stronger now. Upgrade your parts.' },
  'baekgu.pirateMax':            { ko: '해적 전투력 최대치. 최고 장비 갖춰.',
                                   en: 'Pirate power is maxed out. Get top-tier gear.' },
  'baekgu.stayWarning':          { ko: '같은 자리에 너무 오래 있으면 해적들이 냄새 맡는다. 다음 턴엔 이동해.',
                                   en: 'Stay too long and pirates will sniff us out. Move next turn.' },
  'baekgu.barelyEscaped':        { ko: '간신히 따돌렸어. 항로 주의해.',
                                   en: 'Barely shook them off. Watch the route.' },
