  'baekgu.searchStart':          { ko: '탐색 시작. 잔해 구역 접근 중.',
                                   en: 'Beginning search. Approaching the debris zone.' },
  'baekgu.searchNothing':        { ko: '이번엔 없네. 다시 탐색해봐.',
                                   en: 'Nothing this time. Try searching again.' },
  'baekgu.searchNothingAlt':     { ko: '이번엔 별다른 게 없네. 다시 시도해봐.',
                                   en: 'Nothing special this time. Try again.' },
  'baekgu.searchCompleteQuest':  { ko: '잔해 탐색 완료. 퀘스트 보상 받아.',
                                   en: 'Debris search complete. Claim your quest reward.' },
  'baekgu.searchPartial':        { ko: '잔해 일부 발견. 계속 탐색해야 해.',
                                   en: 'Found partial debris. Keep searching.' },
  'baekgu.deliveryArrived':      { ko: '목적지 도착. 퀘스트 탭에서 보상 받아.',
                                   en: 'Arrived at destination. Claim the reward in the Quest tab.' },
