  'ship.F03_M.desc': { ko: '메카니카 산업 중형함. 파츠 슬롯 10개 · TEC 최강 · 자동 수리 1%/턴 · 화물 16칸',
                      en: 'Mechanica industrial medium ship. 10 part slots · top TEC · auto-repair 1%/turn · 16 cargo slots.' },
  'ship.F03_L.nm':   { ko: '옴니코어 프라임', en: 'Omnicore Prime' },
  'ship.F03_L.desc': { ko: '메카니카 슈퍼AI 기함. INT 118 · TEC 100 · 매 턴 적 1척 TEC -10% · 화물 24칸',
                      en: 'Mechanica super-AI flagship. INT 118 · TEC 100 · one enemy TEC -10% per turn · 24 cargo slots.' },
  // F04 크리그
  'ship.F04_S.nm':   { ko: '워액스',       en: 'War Axe' },
  'ship.F04_S.desc': { ko: '크리그 돌격 정찰기. ATT 52 (소형 최강) · 첫 턴 크리티컬 +15% · 화물 8칸',
                      en: 'Krieg assault scout. ATT 52 (top small) · turn-1 Critical +15% · 8 cargo slots.' },
  'ship.F04_M.nm':   { ko: '블러드해머',   en: 'Bloodhammer' },
  'ship.F04_M.desc': { ko: '크리그 전투 순양함. ATT 78 (중형 최강) · 근접 ATT +25% · 화물 16칸',
                      en: 'Krieg combat cruiser. ATT 78 (top medium) · melee ATT +25% · 16 cargo slots.' },
  'ship.F04_L.nm':   { ko: '블레이드 오브 크리그', en: 'Blade of Krieg' },
  'ship.F04_L.desc': { ko: '크리그 군단 기함. ATT 122 (대형 최강) · 전투 시작 시 적 기함 ATT -15% · 화물 24칸',
                      en: 'Krieg legion flagship. ATT 122 (top large) · battle start: enemy flagship ATT -15% · 24 cargo slots.' },
  // F05 치크스 (노획선)
  'ship.CHIX_S_BUY.nm':   { ko: '치크스 정찰기', en: 'Chiks Scout' },
  'ship.CHIX_S_BUY.desc': { ko: '노획된 치크스 정찰기. 이질적 생체회로로 INT 회복 +10%/턴 · 화물 8칸',
                           en: 'Captured Chiks scout. Alien bio-circuits: INT regen +10%/turn · 8 cargo slots.' },
  'ship.CHIX_M_BUY.nm':   { ko: '치크스 순양함', en: 'Chiks Cruiser' },
  'ship.CHIX_M_BUY.desc': { ko: '노획된 치크스 중형 순양함. 치크스 함대 상대로 ATT +25% · 화물 16칸',
                           en: 'Captured Chiks medium cruiser. ATT +25% vs Chiks fleets · 16 cargo slots.' },
  'ship.CHIX_L_BUY.nm':   { ko: '치크스 모선',   en: 'Chiks Mothership' },
  'ship.CHIX_L_BUY.desc': { ko: '노획된 치크스 모선. 전투 시작 시 적 1척 마비(1턴) · 화물 24칸',
                           en: 'Captured Chiks mothership. Battle start: paralyzes one enemy (1 turn) · 24 cargo slots.' },
  // F06 지구 저항군
  'ship.F06_S.nm':   { ko: '자유의 횃불',   en: 'Torch of Liberty' },
  'ship.F06_S.desc': { ko: '지구저항군 정찰기. HP 620 (소형 최상) · 매 턴 HP +1% · LOY 96 · 화물 8칸',
                      en: 'Earth Resistance scout. HP 620 (top small) · HP +1%/turn · LOY 96 · 8 cargo slots.' },
  'ship.F06_M.nm':   { ko: '게릴라 와스프', en: 'Guerrilla Wasp' },
  'ship.F06_M.desc': { ko: '화성·달 게릴라 순양함. HP 7500 (중형 최상) · 수리 효율 +25% · 자국령 ATT +10% · 화물 16칸',
                      en: 'Mars/Moon guerrilla cruiser. HP 7500 (top medium) · repair efficiency +25% · home territory ATT +10% · 16 cargo slots.' },
  'ship.F06_L.nm':   { ko: '어스 다이어울프', en: 'Earth Direwolf' },
  'ship.F06_L.desc': { ko: '지구저항군 결사 기함. HP 25000 · 함대 HP +1%/턴 · 자국령 행성당 INT +1% (캡 +10%) · 화물 24칸',
                      en: 'Earth Resistance vanguard flagship. HP 25000 · fleet HP +1%/turn · INT +1% per home planet (cap +10%) · 24 cargo slots.' },
  // F07 보이드
  'ship.F07_S.nm':   { ko: '보이드 위스퍼', en: 'Void Whisper' },
  'ship.F07_S.desc': { ko: '★ 보이드 최상위 정찰기. 전 스탯 소형 최강(×1.5) · 회피율 +12% · 보이드 행성에서 ATT +10% · 화물 8칸',
                      en: '★ Top-tier Void scout. All stats top small (×1.5) · evasion +12% · ATT +10% on Void planets · 8 cargo slots.' },
  'ship.F07_M.nm':   { ko: '리프트 시커',   en: 'Rift Seeker' },
  'ship.F07_M.desc': { ko: '★ 보이드 최상위 중형함. 전 스탯 중형 최강(×1.5) · 전투 시작 시 적 INT -10% (전투 내내) · 화물 16칸',
                      en: '★ Top-tier Void medium ship. All stats top medium (×1.5) · battle start: enemy INT -10% (entire battle) · 16 cargo slots.' },
  'ship.F07_L.nm':   { ko: '메아리 군주',   en: 'Echo Sovereign' },
  'ship.F07_L.desc': { ko: '★★ 보이드 최강 기함. 전 스탯 대형 최강(×1.5) · INT/TEC 압도 · 매 턴 적 1척 회피율 -20% · 실드 침투 +10% · 화물 24칸',
                      en: '★★ Top Void flagship. All stats top large (×1.5) · INT/TEC dominance · one enemy evasion -20% per turn · shield penetration +10% · 24 cargo slots.' },

  // ── 최종 보스 함선 (BOSS) + 친위대 호위(BOSS_ESCORT) ───────────────
