  'ship.greek.alpha':   { ko: '알파',    en: 'Alpha' },
  'ship.greek.beta':    { ko: '베타',    en: 'Beta' },
  'ship.greek.gamma':   { ko: '감마',    en: 'Gamma' },
  'ship.greek.delta':   { ko: '델타',    en: 'Delta' },
